8	/**
9	 * Rejects a create whose normalized telephone is already used by any other owner,
10	 * before {@link SaveOwner} runs. Handled with 409 by {@code DuplicateTelephoneHandler}.
11	 */
12	public class CheckUniqueTelephone {
13	
14	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
15	            throws DuplicateTelephoneException {
16	        String telephone = owner.getTelephone();
17	        for (Owner other : ownerRepository.findAll()) {
18	            if (!other.getId().equals(owner.getId())
19	                    && telephone.equals(other.getTelephone())) {
20	                throw new DuplicateTelephoneException(telephone);
21	            }
22	        }
23	    }
24	}
