8	/**
9	 * Rejects a create whose lastName and address already belong to another owner (compared
10	 * case-insensitively with collapsed whitespace), before {@link SaveOwner} runs. Handled
11	 * with 409 by {@code DuplicateHouseholdHandler}. Skipped when the request opts in with
12	 * {@code sharesHousehold=true}.
13	 */
14	public class CheckUniqueHousehold {
15	
16	    public void service(@Val Owner owner, @Val Boolean sharesHousehold, OwnerRepository ownerRepository)
17	            throws DuplicateHouseholdException {
18	        if (Boolean.TRUE.equals(sharesHousehold)) {
19	            return;
20	        }
21	        String lastName = normalize(owner.getLastName());
22	        String address = normalize(owner.getAddress());
23	        for (Owner other : ownerRepository.findAll()) {
24	            if (!other.getId().equals(owner.getId())
25	                    && lastName.equals(normalize(other.getLastName()))
26	                    && address.equals(normalize(other.getAddress()))) {
27	                throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
28	            }
29	        }
30	    }
31	
32	    /** Lower-cases and collapses runs of whitespace to a single space so that
33	     *  case and spacing differences do not defeat the household match. */
34	    static String normalize(String value) {
35	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
36	    }
37	}
