3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * When the request opts in with {@code sharesHousehold=true}, assigns a stable
12	 * {@code householdId} derived from the owner's normalized lastName and address, so every
13	 * owner sharing that household resolves to the same identifier. Runs before
14	 * {@link SaveOwner}; a no-op otherwise, leaving {@code householdId} absent.
15	 */
16	public class AssignHouseholdId {
17	
18	    public void service(@Val Owner owner, @Val Boolean sharesHousehold) {
19	        if (!Boolean.TRUE.equals(sharesHousehold)) {
20	            return;
21	        }
22	        String key = CheckUniqueHousehold.normalize(owner.getLastName())
23	                + "|" + CheckUniqueHousehold.normalize(owner.getAddress());
24	        owner.setHouseholdId(hash(key));
25	    }
26	
27	    /** First 8 bytes of SHA-256({@code key}) as lower-case hex — stable across requests. */
28	    static String hash(String key) {
29	        try {
30	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
31	            StringBuilder sb = new StringBuilder(16);
32	            for (int i = 0; i < 8; i++) {
33	                sb.append(String.format("%02x", digest[i]));
34	            }
35	            return sb.toString();
36	        }
37	        catch (NoSuchAlgorithmException e) {
38	            throw new IllegalStateException(e);
39	        }
40	    }
41	}
