3	import java.util.Map;
4	
5	/**
6	 * Per-country E.164 national-number length rule. A valid number is a supported
7	 * country code followed by exactly that country's national-digit count
8	 * ('+61' -> 9 national digits, '+1' -> 10). Anything else is rejected.
9	 */
10	final class E164Length {
11	
12	    /** Country calling code (no '+') -> required national-number length. */
13	    private static final Map<String, Integer> NATIONAL_DIGITS = Map.of("61", 9, "1", 10);
14	
15	    private E164Length() {
16	    }
17	
18	    /** True when {@code digits} (country code + national number, no '+') matches a known country's length. */
19	    static boolean isValid(String digits) {
20	        for (Map.Entry<String, Integer> country : NATIONAL_DIGITS.entrySet()) {
21	            String code = country.getKey();
22	            if (digits.startsWith(code) && digits.length() - code.length() == country.getValue()) {
23	                return true;
24	            }
25	        }
26	        return false;
27	    }
28	}
